/*
 * DSH Bot PWA service worker.
 *
 * Generated by ui/pwa/build-shell.mjs. Do not edit a built copy: edit the template,
 * `routes.js`, or the generator, then rebuild the workbench UI.
 *
 * Contract (docs/pwa-instant-start.md):
 * - Cache-first only for the versioned shell document and its entry assets.
 * - Every API, SSE, capability, workspace, and update request is left to the network.
 * - No network response is ever written to Cache Storage.
 * - The new version waits; a page decides when to skipWaiting.
 */
'use strict'

const RELEASE_ID = '__RELEASE_ID__'
const PRECACHE = __PRECACHE__
const SHELL_CACHE_PREFIX = 'dsh-bot-shell-'
const SHELL_CACHE = SHELL_CACHE_PREFIX + RELEASE_ID
const SHELL_META_CACHE = 'dsh-bot-shell-meta'
const META_KEY = '/__dsh-bot-shell-meta__'
const SHELL_INDEX = '/dsh-bot/index.html'

__ROUTES__

self.addEventListener('install', event => {
  event.waitUntil(precacheShell())
})

self.addEventListener('activate', event => {
  event.waitUntil(activateShell())
})

self.addEventListener('fetch', event => {
  const route = self.DshBotPwa.classify(event.request)
  if (route === 'shell') event.respondWith(shellDocument(event.request))
  else if (route === 'asset') event.respondWith(shellAsset(event.request))
  // 'bypass' and 'network': no respondWith, no caches.put.
})

self.addEventListener('message', event => {
  const data = event.data
  if (!data || typeof data !== 'object') return
  if (data.type === 'SKIP_WAITING') {
    self.skipWaiting()
    return
  }
  if (data.type === 'GET_RELEASE') {
    const payload = { type: 'DSH_BOT_PWA_RELEASE', releaseId: RELEASE_ID, cache: SHELL_CACHE }
    const port = event.ports && event.ports[0]
    if (port) port.postMessage(payload)
    else if (event.source && typeof event.source.postMessage === 'function') event.source.postMessage(payload)
  }
})

async function sha256Hex(buffer) {
  const digest = await crypto.subtle.digest('SHA-256', buffer)
  const bytes = new Uint8Array(digest)
  let hex = ''
  for (const byte of bytes) hex += byte.toString(16).padStart(2, '0')
  return hex
}

/** All entries or nothing: a partial bucket must never become the active shell. */
async function precacheShell() {
  if (!Array.isArray(PRECACHE) || PRECACHE.length === 0) {
    throw new Error('dsh-bot pwa: empty precache list')
  }
  const cache = await caches.open(SHELL_CACHE)
  try {
    for (const entry of PRECACHE) {
      const request = new Request(entry.url, { cache: 'no-store', credentials: 'same-origin' })
      const response = await fetch(request)
      if (!response.ok) throw new Error('dsh-bot pwa: ' + entry.url + ' responded ' + response.status)
      if (entry.hash && typeof crypto.subtle?.digest === 'function') {
        const hex = await sha256Hex(await response.clone().arrayBuffer())
        if (hex.slice(0, entry.hash.length) !== entry.hash) {
          throw new Error('dsh-bot pwa: hash mismatch for ' + entry.url)
        }
      }
      await cache.put(entry.url, response)
    }
  } catch (error) {
    await caches.delete(SHELL_CACHE)
    throw error
  }
}

async function activateShell() {
  const metaCache = await caches.open(SHELL_META_CACHE)
  const meta = await readMeta(metaCache)
  const previous =
    typeof meta.releaseId === 'string' && meta.releaseId !== '' && meta.releaseId !== RELEASE_ID
      ? SHELL_CACHE_PREFIX + meta.releaseId
      : ''
  const keep = new Set([SHELL_CACHE, SHELL_META_CACHE])
  if (previous !== '') keep.add(previous)

  for (const name of await caches.keys()) {
    if (name.startsWith(SHELL_CACHE_PREFIX) && !keep.has(name)) await caches.delete(name)
  }

  await writeMeta(metaCache, {
    releaseId: RELEASE_ID,
    previous: typeof meta.releaseId === 'string' ? meta.releaseId : '',
  })

  const clients = await self.clients.matchAll({ type: 'window' })
  for (const client of clients) {
    client.postMessage({ type: 'DSH_BOT_PWA_ACTIVE', releaseId: RELEASE_ID })
  }
}

/**
 * A document navigation, resolved against the network first.
 *
 * Serving the cached document before asking the origin is what hid Cloudflare Access:
 * an expired session answers the navigation with a redirect, and a cached reply meant
 * that redirect never happened. The origin gets the first word now.
 *
 * This worker deliberately knows nothing about sessions. It only refuses to stand in
 * for a document the network wanted to say something about: a redirect is handed back
 * to the browser so whatever owns authentication runs natively, and every other answer
 * is returned unchanged. The cached shell is only for a request that could not complete.
 */
const PROBE_TIMEOUT_MS = 5000

async function shellDocument(request) {
  const probe = await probeNavigation(request)
  const action = self.DshBotPwa.navigationAction(probe)
  if (action === 'handoff') return Response.redirect(probe.url, 302)
  if (action === 'network') return probe
  const cached = await matchShell(SHELL_INDEX)
  return cached || Response.error()
}

/** Ask the origin for the document, following any redirect to observe where it ends. */
async function probeNavigation(request) {
  try {
    return await withTimeout(
      fetch(request.url, {
        method: 'GET',
        credentials: 'same-origin',
        redirect: 'follow',
        cache: 'no-store',
        headers: { accept: 'text/html' },
      }),
      PROBE_TIMEOUT_MS,
    )
  } catch {
    return null
  }
}

function withTimeout(promise, ms) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('dsh-bot pwa: navigation probe timed out')), ms)
    promise.then(
      value => {
        clearTimeout(timer)
        resolve(value)
      },
      error => {
        clearTimeout(timer)
        reject(error)
      },
    )
  })
}

/**
 * A versioned shell asset: the current bucket, then the previous one so a tab opened
 * before the last activation keeps working, then the network. Stays cache-first.
 */
async function shellAsset(request) {
  const url = new URL(request.url)
  const cached = await matchShell(url.pathname)
  if (cached) return cached
  return fetch(request)
}

async function matchShell(key) {
  const current = await caches.open(SHELL_CACHE)
  const hit = await current.match(key)
  if (hit) return hit
  const meta = await readMeta(await caches.open(SHELL_META_CACHE))
  const previous = typeof meta.previous === 'string' ? meta.previous : ''
  if (previous === '' || previous === RELEASE_ID) return undefined
  const older = await caches.open(SHELL_CACHE_PREFIX + previous)
  return older.match(key)
}

async function readMeta(cache) {
  try {
    const response = await cache.match(META_KEY)
    if (!response) return {}
    const value = await response.json()
    return value && typeof value === 'object' ? value : {}
  } catch {
    return {}
  }
}

async function writeMeta(cache, value) {
  const body = JSON.stringify(value)
  await cache.put(
    META_KEY,
    new Response(body, { headers: { 'content-type': 'application/json', 'content-length': String(body.length) } }),
  )
}
